        vm.deal(address(this), 1 ether);
        (bool s, ) = address(c).call{value: 1 ether}("");
        assertTrue(s);

        vm.prank(actor);
        c.getFirstWithdrawalBonus(actor);
        uint256 balAfterBonus = address(c).balance;

        vm.prank(actor);
        c.withdrawReward(actor);

        // Rule: reward was zeroed by the first payout, so this withdrawal pays 0.
        assertEq(address(c).balance, balAfterBonus);
    }
}

