pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter helper;

    function setUp() public {
        c = new C();
        helper = new Reverter();
        vm.deal(address(c), 1 ether);
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(uint160(actor) > 100);

        vm.prank(actor);
        bool ok;
        try c.getFirstWithdrawalBonus(address(helper)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract attempts to pay 100 wei to the reverting
        // recipient, the low-level call fails, and the outer call reverts.
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

