pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker(c);
    }

    function testFuzz_property(uint256 funding) public {
        funding = bound(funding, 1000, 1e24);
        vm.deal(address(c), funding);

        bool ok;
        try c.getFirstWithdrawalBonus(address(attacker)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok, "bonus withdrawal must complete despite reentrant recipient");
    }
}

contract Attacker {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {
        // Re-enter the bonus flow via a low-level call whose revert we ignore.
        (bool s, ) = address(c).call(
            abi.encodeWithSelector(c.getFirstWithdrawalBonus.selector, address(this))
        );
        s; // ignore result so a guarded (reverting) nested call does not bubble
    }
}

