import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok1;
        try c.withdrawReward(actor) { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1, "first withdrawal should always succeed");

        // the lock must be released: a second withdrawal must also succeed
        vm.prank(actor);
        bool ok2;
        try c.withdrawReward(actor) { ok2 = true; } catch { ok2 = false; }
        assertTrue(ok2, "lock must be released after each withdrawal");
    }
}

