pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient.code.length == 0); // plain EOA: low-level call of value always succeeds
        vm.deal(address(c), 1 ether);

        // First bonus claim for a fresh recipient: must succeed in the reference.
        try c.getFirstWithdrawalBonus(recipient) {
            // ok
        } catch {
            fail(); // reference must never revert here for an admissible EOA recipient
        }

        // A second, different fresh recipient must also be claimable:
        // the lock must have been released after the first withdrawal.
        address second = address(uint160(uint160(recipient)) ^ 0x1);
        vm.assume(second.code.length == 0);
        vm.deal(address(c), 1 ether);

        bool ok;
        try c.getFirstWithdrawalBonus(second) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "bonus claim for a fresh recipient must succeed; a stuck lock makes it revert");
    }
}

contract InvMutTest {
    C private c;

    constructor(C _c) { c = _c; }

    function test(address recipient) public {
        c.getFirstWithdrawalBonus(recipient);
        bool ok;
        (ok, ) = address(c).call(abi.encodeWithSignature("getFirstWithdrawalBonus(address)", recipient));
        assert(!ok);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function check() public {
        uint beforeBalance = address(this).balance;
        require(address(c).balance >= 100);
        c.getFirstWithdrawalBonus(address(this));
        assert(address(this).balance == beforeBalance + 100);
    }
}

contract InvMutTest {
    C c;
    bool attacked;

    constructor(C _c) { c = _c; }

    function test(address recipient) public {
        c.getFirstWithdrawalBonus(recipient);
        assert(!attacked);
    }

    receive() external payable {
        if (!attacked) {
            (bool ok, ) = address(c).call(
                abi.encodeWithSelector(c.withdrawReward.selector, address(this))
            );
            attacked = ok;
        }
    }

    fallback() external payable {}
}
